INSERT INTO `companies` (`id`, `name`, `email`, `phone`, `status`, `city`, `address`, `country`, `admin`, `timezone`, `currency`, `payment_details`, `kra_pin`, `booking_form`, `car_diagram`, `booking_disclaimer_in`, `booking_disclaimer_out`, `booking_terms`, `invoice_disclaimer`, `quote_disclaimer`, `invoice_signing`, `quote_signing`, `logo`, `sms_balance`, `sms_tasks`, `insurance`, `parts_to_inventory`, `forced_completion`, `forced_checkout`, `restricted_checkout`, `vat`, `subscription_status`, `subscription_plan`, `subscription_start`, `subscription_end`, `subscription_cycle`, `subscription_cancelled`, `subscription_stripe`, `on_trial`, `last_activity`, `created_at`) VALUES
(1, 'Union Star Auto Garage', 'info@usa_garage.com', '+971505522446', 'Active', 'Dubai', 'Dubai , UAE', 'United Arab Emirates', 'Yes', 'Asia/Dubai', 'AED', '', '', 'Detailed', 'Enabled', 'Union Star Auto Garage shall not be held responsible for any loss of personal belongings left inside the vehicle. Customers are advised to remove all valuables before handing over the vehicle.', 'confirm that all outstanding charges related to the vehicle service, repairs, parts, storage fees (if applicable), and other authorized work have been settled or agreed upon.', 'UNION STAR AUTO GARAGE\r\n\r\nTERMS &amp; CONDITIONS\r\n\r\n1. Vehicle Inspection\r\n   All vehicles are inspected upon arrival. Union Star Auto Garage is not responsible for any pre-existing damage, defects, or faults not reported before service commencement.\r\n\r\n2. Repair Authorization\r\n   By approving a job card, estimate, quotation, or booking form, the customer authorizes Union Star Auto Garage to perform the requested repairs, diagnostics, maintenance, and related services.\r\n\r\n3. Additional Repairs\r\n   If additional faults are discovered during inspection or repair, the customer will be informed for approval before any additional work is carried out.\r\n\r\n4. Parts &amp; Materials\r\n   Union Star Auto Garage may use genuine, OEM, or approved aftermarket parts depending on availability and customer approval. Prices are subject to change based on supplier costs.\r\n\r\n5. Warranty\r\n   Warranty coverage applies only to parts and services specifically stated on the invoice. Warranty does not cover misuse, accidents, negligence, normal wear and tear, or repairs performed by third parties.\r\n\r\n6. Customer Property\r\n   Customers are advised to remove all personal belongings and valuables from the vehicle. Union Star Auto Garage shall not be liable for loss, theft, or damage to personal items left inside the vehicle.\r\n\r\n7. Vehicle Collection\r\n   Vehicles must be collected promptly after notification of completion. Storage charges may apply to vehicles left uncollected for an extended period.\r\n\r\n8. Payment Terms\r\n   Full payment is due upon completion of services unless otherwise agreed in writing. Union Star Auto Garage reserves the right to retain possession of the vehicle until all outstanding balances are paid in full.\r\n\r\n9. Road Testing\r\n   The customer authorizes Union Star Auto Garage to operate and road-test the vehicle when necessary for diagnostics, repair verification, or quality assurance purposes.\r\n\r\n10. Limitation of Liability\r\n    Union Star Auto Garage shall not be liable for indirect, incidental, special, or consequential damages arising from vehicle repairs, maintenance, delays, or service interruptions.\r\n\r\n11. Estimate Validity\r\n    All quotations and estimates are valid for 30 days unless otherwise stated. Final charges may vary if additional issues are identified during repair.\r\n\r\n12. Customer Acceptance\r\n    By signing any booking form, job card, estimate, invoice, or service authorization, the customer confirms acceptance of these Terms &amp; Conditions.\r\n\r\n', 'Union Star Auto Garage shall not be liable for any pre-existing defects, normal wear and tear, or damages resulting from misuse, accidents, or unauthorized repairs. All invoices are payable upon receipt. By accepting this invoice, the customer agrees to the garage&#039;s terms and conditions.\r\n', 'Union Star Auto Garage is not liable for pre-existing defects, normal wear and tear, or damages caused by misuse, accidents, or unauthorized repairs. By accepting this invoice, the customer agrees to our terms and conditions.', 'Enabled', 'Enabled', '1Zu7jw4U94X9QFzPb56YZQipAdvmveHg.png', 0.00, 'Disabled', 'Enabled', 'Enabled', 'Enabled', 'Enabled', 'Enabled', 0.00, 'Expired', NULL, '2021-04-15', '2022-05-15', 'Annually', 'No', NULL, 'No', '2026-08-08 07:48:01', '2020-08-11 18:03:58'),
